        <Stepper Minimum ="0" Maximum="10" Increment ="0.1" VerticalOptions = "Start" 
                 ValueChanged="OnStepperValueChanged" />
        <Label x:Name="header"  FontSize="18" Margin="5" />
    </StackLayout>
</ContentPage>
```

