    <Slider Minimum ="0" Maximum="50" Value="30" ValueChanged="OnSliderValueChanged" 
        MinimumTrackColor="DeepPink" MaximumTrackColor="LightPink" ThumbColor="DeepPink" />
</StackLayout>
